const classTasks={
  'AR':['Kafadan vuruşla 50 oyuncu ele.','Kafadan vuruşla 100 düşman ele.','25 çift eleme yap.','50 çift eleme yap.'],
  'SMG':['Arkadan 25 oyuncu ele.','Arkadan 75 düşman ele.','Nişan almadan (Hipfire) 50 oyuncu ele.','Nişan almadan (Hipfire) 100 düşman ele.'],
  'Pompalı':['Nişan almadan 50 oyuncu ele.','Nişan almadan 125 düşman ele.','Şarjör değiştirmeden 2 oyuncu ele; 25 kez.','Şarjör değiştirmeden 2 düşman ele; 50 kez.'],
  'LMG':['Ölmeden 3 oyuncu ele; 15 kez.','Hasar almadan 3 düşman ele; 50 kez.','Tetiği bırakmadan 2 oyuncu ele; 25 kez.','Tetiği bırakmadan 2 düşman ele; 75 kez.'],
  'Nişancı':['Yere yatarak 75 oyuncu ele.','Yere yatarak düşman ele; sayı doğrulanmadı.','75 tek atış elemesi yap.','Tek atışla eleme yap; sayı doğrulanmadı.'],
  'Keskin nişancı':['Yere yatarak 75 oyuncu ele.','Yere yatarak 150 düşman ele.','75 tek atış elemesi yap.','150 tek atış elemesi yap.'],
  'Tabanca':['Arkadan 20 oyuncu ele.','Arkadan 75 düşman ele.','Nişan almadan 40 oyuncu ele.','Nişan almadan 100 düşman ele.'],
  'Roketatar':['Hasar almadan 2 oyuncu ele; 15 kez.','Hasar almadan 2 düşman ele; 50 kez.','Bir maçta 10 oyuncu ele; 7 kez.','Bir maçta 10 düşman ele; 15 kez.'],
  'Yakın dövüş':['Ölmeden 3 oyuncu ele; 15 kez.','Hasar almadan 3 düşman ele; 50 kez.','Arkadan 25 oyuncu ele.','Arkadan 75 düşman ele.']
};
function escapeText(text){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function requirements(mp,dmz){return `<span class="requirement"><em>MP</em><span>${escapeText(mp)}</span></span><span class="requirement"><em>DMZ</em><span>${escapeText(dmz)}</span></span>`}
function specialRequirement(w, s, i, mode) {
  const max = s[mode + 'Target'];
  const key = (typeof i==='number'?'sp'+i:i) + mode;
  const value = get(w.id)[key] || 0;
  const field = max ? `<label class="special-counter"><input type="number" min="0" max="${max}" step="1" inputmode="numeric" data-owner="${w.id}" data-special="${key}" value="${value}" aria-label="${escapeText(s.name)} ${mode.toUpperCase()} ilerlemesi"><b>/${max}</b></label>` : '<small>Tekrar hedefi doğrulanmadı</small>';
  return `<div class="requirement"><em>${mode.toUpperCase()}</em><span>${escapeText(s[mode])} ${field}</span></div>`;
}
function specialTask(w,s,i){const checked=!!get(w.id)['sp'+i];return `<article class="special-task ${checked?'done':''}"><div class="special-image"><img loading="lazy" src="${image(s.slug)}" alt="${escapeText(s.name)} kamuflaj deseni"><label class="complete"><input type="checkbox" data-check="sp${i}" ${checked?'checked':''} aria-label="${escapeText(s.name)} tamamlandı"> Tamamlandı</label></div><div class="special-copy"><h3>${escapeText(s.name)}</h3><p class="unlock">${s.level?'Açılma koşulu: Silah seviyesi '+s.level:'Açılma seviyesi doğrulanmadı'}</p>${['mp','dmz'].map(mode=>specialRequirement(w,s,i,mode)).join('')}${s.warning?`<p class="data-note">${escapeText(s.warning)}</p>`:''}<a class="source-status" href="${escapeText(s.source)}" target="_blank" rel="noopener">${s.verified?'Resmî kaynak':'Topluluk kaynağı · resmî teyit yok'} ↗</a></div></article>`}
function completionInfo(w,c){const idx=c[0]==='platinum'?0:2;let mp,dmz;if(c[0]==='gold'){mp='Tek bir maçta 15 oyuncu ele.';dmz='Tek bir görevde 100 düşman ele.';}else if(c[0]==='platinum'){[mp,dmz]=classTasks[w.category];}else{mp=classTasks[w.category][idx];dmz=classTasks[w.category][idx+1];}
const target=text=>text.includes('doğrulanmadı')?null:Number(text.match(/\d+/g)?.at(-1))||null;
return {name:c[1],mp,dmz,mpTarget:target(mp),dmzTarget:target(dmz)};
}
function trackedTasks(w){
  return [...weaponTasks[w.id].specials.map((s,i)=>['sp'+i,s]), ...camos.slice(0,3).map(c=>[c[0],completionInfo(w,c)])];
}
function militaryLevels(id){ return id==='han-86'?[10,18,25,34,42,50,57,65]:id==='apoc-338'?[9,15,22,26,33,40,44,51]:null; }
function completionTask(w,c){const d=get(w.id),idx=c[0]==='platinum'?0:2;let mp,dmz,gate;if(c[0]==='gold'){mp='Tek bir maçta 15 oyuncu ele.';dmz='Tek bir görevde 100 düşman ele.';gate=`Ön koşul: Bu silahta 8 Military + 3 Special (${boolKeys.slice(0,11).filter(k=>d[k]).length}/11).`;}else if(c[0]==='platinum'){[mp,dmz]=classTasks[w.category];const siblings=weapons.filter(x=>x.category===w.category);gate=`Ön koşul: ${w.category} sınıfındaki tüm silahlarda Gold (${siblings.filter(x=>get(x.id).gold).length}/${siblings.length}).`;}else{mp=classTasks[w.category][idx];dmz=classTasks[w.category][idx+1];gate=`Ön koşul: 33 silahta Platinum (${total('platinum')}/33).`;}
return `<article class="special-task ${d[c[0]]?'done':''}"><div class="special-image"><img src="${image(c[2])}" alt="${c[1]} deseni"><label class="complete"><input type="checkbox" data-check="${c[0]}" ${d[c[0]]?'checked':''} aria-label="${c[1]} tamamlandı"> Tamamlandı</label></div><div class="special-copy"><h3>${c[1]}</h3><p class="unlock">${gate}</p>${['mp','dmz'].map(m=>specialRequirement(w,completionInfo(w,c),c[0],m)).join('')}${c[0]!=='gold'?'<p class="data-note">Sınıf görevleri; resmî sayı verilmeyen yerlerde topluluk rehberleri kullanılır.</p>':''}</div></article>`}
function renderWeaponDetail(){const w=weapons.find(w=>w.id===selected),d=get(selected);$('#detail').innerHTML=`<div class="detail-head"><div><small>${w.category.toUpperCase()}</small><h2>${w.name}</h2><p>${progress(selected)} / 14 ana adım tamamlandı</p></div><button id="favorite" aria-label="Favori durumunu değiştir" aria-pressed="${!!d.favorite}" class="star">${d.favorite?'★':'☆'}</button></div><label class="weapon-level">Silah seviyem <input class="count" type="number" min="0" step="1" data-level value="${d.level||0}"></label><label class="weapon-level"><input type="checkbox" data-check="p1" ${hasPrestigeOne(d)?'checked':''} ${(d.p2||d.p3||d.p4||d.masterLevel>0)?'disabled':''}> Silah Prestij 1’e ulaştı</label><div class="detail-tabs">${[['camo','Kamuflajlar'],['prestige','Prestij · 4 aşama'],['mastery','Mod ustalığı']].map(([id,title])=>`<button data-tab="${id}" class="${detailTab===id?'active':''}">${title}</button>`).join('')}</div><div class="detail-content" id="detailContent"></div>`;
let html='';if(detailTab==='camo'){
const levels=militaryLevels(w.id);
html=`<div class="group-title">Military <small>Silah seviyesini yükselterek açılır</small></div><div class="checks">${military.map((name,i)=>`<label class="swatch ${d['mil'+i]?'done':''}"><img src="${image(name)}" alt="${name} deseni"><input type="checkbox" data-check="mil${i}" ${d['mil'+i]?'checked':''}><span>${i+1} · ${name.replaceAll('-',' ')}<strong>${levels?'Seviye '+(d['mil'+i]?levels[i]:Math.min(d.level||0,levels[i]))+'/'+levels[i]:'Seviye teyidi bekleniyor'}</strong></span></label>`).join('')}</div><div class="group-title">${w.name} · Special <small>3 ayrı kamuflaj</small></div><p class="mode-help">Görevi bu silahla tamamla. MP veya DMZ koşulundan birini bitirmen yeterli.</p>`;
html+=weaponTasks[w.id].specials.map((s,i)=>specialTask(w,s,i)).join('');html+='<div class="group-title">Completionist <small>Ön koşul + görev</small></div>'+camos.slice(0,3).map(c=>completionTask(w,c)).join('');html+=`<div class="notice"><b>Divergence</b><br>33 silahta Harmonic Break tamamla (${total('harmonic')}/33). Ek eleme görevi yok; otomatik açılır.</div>`;
}else if(detailTab==='prestige'){html='<div class="notice">Önce silahı maksimum seviyeye getir ve Prestij 1’e gir. Bu dört ödül ana kamuflaj görevlerinden bağımsızdır.</div>'+`<label class="weapon-level">Silah Prestij Master seviyem <input type="number" class="count" data-master min="0" max="250" value="${d.masterLevel||0}"></label>`+camos.slice(10).map(c=>task(c[0],c[1],c[3]+' · '+(c[0]==='p3'||c[0]==='p4'?Math.min(d[c[0]]?(c[0]==='p3'?150:250):d.masterLevel||0,c[0]==='p3'?150:250)+'/'+(c[0]==='p3'?150:250):(d[c[0]]?'1/1':'0/1')),c[2])).join('');}
else{html=`<div class="mode"><button data-mode="mp" class="${mode==='mp'?'active':''}">Multiplayer</button><button data-mode="dmz" class="${mode==='dmz'?'active':''}">DMZ</button></div>`;html+=camos.filter(c=>c[0].startsWith(mode)).map((c,i)=>`<label class="task"><img src="${image(c[2])}" alt="${c[1]}"><div><b>${c[1]}</b><small>Ön koşul: ${i===0?'Divergence':camos.filter(x=>x[0].startsWith(mode))[i-1][1]}.</small><small>${c[3]}</small><small>${d[c[0]]||0} / ${targets[c[0]]}</small></div><input class="count" type="number" min="0" max="${targets[c[0]]}" step="1" data-count="${c[0]}" aria-label="${c[1]} ilerlemesi" value="${d[c[0]]||0}"></label>`).join('');}
html+='<div class="group-title">Kendi notun <small>Otomatik kaydedilir</small></div><textarea class="notes" id="note" maxlength="2000" placeholder="Kalan görev veya oyun içindeki güncel gereksinim…" aria-label="Silah notu"></textarea>';$('#detailContent').innerHTML=html;$('#note').value=d.note||'';}
